import type { Budget, BlastRadiusResult, IDependencyGraph } from '../../../specs/interfaces/core';

export class DependencyGraph implements IDependencyGraph {
  private imports = new Map<string, Set<string>>();
  private importedBy = new Map<string, Set<string>>();
  private project: Project | null = null;

  async build(rootPath: string, signal?: AbortSignal): Promise<void> {
    this.project = new Project({
      tsConfigFilePath: `${rootPath}/tsconfig.json`,
      skipAddingFilesFromTsConfig: false,
    });

    const files = this.project.getSourceFiles();
    for (const file of files) {
      if (signal?.aborted) throw new Error('Build cancelled');
      this.processFile(file);
      file.forget(); // Release memory after processing
    }
  }

