import type { IDependencyGraph } from '../../core/graph/DependencyGraph';

export class TestMapper implements ITestMapper {
  private testToSource = new Map<string, string>();
  private sourceToTests = new Map<string, Set<string>>();

  constructor(private depGraph: IDependencyGraph) {}

  async findTestsForFile(sourceFile: string): Promise<string[]> {
    // Strategy 1: Convention-based (*.test.ts, *.spec.ts)
    // Strategy 2: Import analysis (tests that import the source)
    // Strategy 3: Co-location (same directory)

    const tests = this.sourceToTests.get(sourceFile);
    if (tests) return [...tests];

    const conventionTests = this.findByConvention(sourceFile);
    const importTests = this.findByImports(sourceFile);

    return [...new Set([...conventionTests, ...importTests])];
  }

  async findSourceForTest(testFile: string): Promise<string | null> {
    return this.testToSource.get(testFile) || null;
  }

  async getTestCoverage(sourceFile: string): Promise<TestCoverage> {
    const testFiles = await this.findTestsForFile(sourceFile);
    // Analyze coverage based on imports and mocks
    return {
      testFiles,
      coveredSymbols: [],
      uncoveredSymbols: [],
      coveragePercent: testFiles.length > 0 ? 50 : 0,
    };
  }

  async refresh(): Promise<void> {
    this.testToSource.clear();
    this.sourceToTests.clear();
    // Rebuild mappings
  }

  private findByConvention(sourceFile: string): string[] { /* ... */ return []; }
  private findByImports(sourceFile: string): string[] { /* ... */ return []; }
}
