export class CallHierarchyResolver implements ICallHierarchyResolver {
  constructor(private callGraphBuilder: ICallGraphBuilder) {}

  async prepareCallHierarchy(
    document: vscode.TextDocument,
    position: vscode.Position
  ): Promise<vscode.CallHierarchyItem | null> {
    const wordRange = document.getWordRangeAtPosition(position);
    if (!wordRange) return null;

    const functionName = document.getText(wordRange);
    const node = await this.callGraphBuilder.getCallHierarchy(
      document.uri.fsPath,
      functionName
    );

    if (!node) return null;

    return this.nodeToCallHierarchyItem(node, document.uri);
  }

  async provideIncomingCalls(
    item: vscode.CallHierarchyItem
  ): Promise<vscode.CallHierarchyIncomingCall[]> {
    const nodeId = this.itemToNodeId(item);
    const callers = this.callGraphBuilder.getCallers(nodeId);

    return callers.map(caller => ({
      from: this.nodeToCallHierarchyItem(caller, vscode.Uri.file(caller.filePath)),
      fromRanges: [new vscode.Range(caller.line - 1, 0, caller.line - 1, 0)],
