import { LRUCache } from 'lru-cache';

export class CacheService implements ICacheService {
  private caches = new Map<string, LRUCache<string, unknown>>();
  private defaultTtl = 5 * 60 * 1000; // 5 minutes

  private getOrCreateCache(namespace: string): LRUCache<string, unknown> {
    if (!this.caches.has(namespace)) {
      this.caches.set(namespace, new LRUCache({ max: 1000, ttl: this.defaultTtl }));
    }
    return this.caches.get(namespace)!;
  }

  get<T>(namespace: string, key: string): T | undefined {
    return this.getOrCreateCache(namespace).get(key) as T | undefined;
  }

  set<T>(namespace: string, key: string, value: T, ttl?: number): void {
    this.getOrCreateCache(namespace).set(key, value, { ttl });
  }

  invalidate(namespace: string, key?: string): void {
    if (key) {
      this.caches.get(namespace)?.delete(key);
    } else {
      this.caches.delete(namespace);
    }
  }

  getStats(): CacheStats {
    let totalSize = 0;
    for (const cache of this.caches.values()) {
      totalSize += cache.size;
    }
    return { namespaces: this.caches.size, totalEntries: totalSize };
  }
}
```

