import Tinypool from 'tinypool';
import { cpus } from 'os';

export class WorkerPool implements IWorkerPool {
  private pool: Tinypool;

  constructor(workerPath: string, maxWorkers = Math.max(1, cpus().length - 1)) {
    this.pool = new Tinypool({
      filename: workerPath,
      maxThreads: maxWorkers,
      idleTimeout: 60000,
    });
  }

  async submit<T, R>(task: string, data: T): Promise<R> {
    return this.pool.run({ task, data }) as Promise<R>;
  }

  getStats(): WorkerPoolStats {
    return {
      pending: this.pool.queueSize,
      threads: this.pool.threads.length,
    };
  }

  async shutdown(): Promise<void> {
    await this.pool.destroy();
  }
}
