import type { IDependencyGraph } from '../../core/graph/DependencyGraph';
import type { ICallGraphBuilder } from '../../core/graph/CallGraphBuilder';
import type { Budget, BlastRadiusResult, RiskLevel } from '../../core/Budget';

export class ImpactCalculator implements IImpactCalculator {
  constructor(
    private depGraph: IDependencyGraph,
    private callGraph: ICallGraphBuilder,
    private budget: Budget
  ) {}

  async calculateBlastRadius(file: string, symbol?: string): Promise<BlastRadiusResult> {
    const result = this.depGraph.getBlastRadius(file, this.budget);

    // Enhance with call graph data if symbol provided
    if (symbol) {
      const callers = this.callGraph.getCallers(symbol);
      // Add callers to dependents
    }

    return {
      ...result,
      riskLevel: this.getRiskLevel(result.blastRadius),
    };
  }

  async getAffectedTests(file: string): Promise<string[]> {
    const deps = this.depGraph.getDependents(file);
    return deps.filter(d => d.includes('.test.') || d.includes('.spec.'));
  }

  getRiskLevel(blastRadius: number): RiskLevel {
    if (blastRadius > 50) return 'critical';
    if (blastRadius > 20) return 'high';
    if (blastRadius > 5) return 'medium';
    return 'low';
  }
}
