import type { IObserver, Signal } from '../../core/signals/types';

export class ObserverRegistry implements IObserverRegistry {
  private observers = new Map<string, IObserver>();

  register(observer: IObserver): void {
    this.observers.set(observer.id, observer);
  }

  unregister(observerId: string): void {
    this.observers.delete(observerId);
  }

  getObservers(): IObserver[] {
    return [...this.observers.values()];
  }

  async runAll(file: string): Promise<Signal<unknown>[]> {
    const signals: Signal<unknown>[] = [];
    const enabledObservers = this.getObservers().filter(o => o.isEnabled());

    await Promise.all(
      enabledObservers.map(async observer => {
        try {
          const result = await observer.observe(file);
          signals.push(...result);
        } catch (error) {
          console.error(`Observer ${observer.id} failed:`, error);
        }
      })
    );

    return signals;
  }

  async runByType(type: ObserverType, file: string): Promise<Signal<unknown>[]> {
    const observer = this.getObservers().find(o => o.type === type && o.isEnabled());
    if (!observer) return [];
    return observer.observe(file);
  }
}
