import type { IObserver, Signal } from '../../core/signals/types';
import { createSignal } from '../../core/signals/Signal';

export class BoundaryObserver implements IObserver {
  id = 'boundary-observer';
  type = 'boundary' as const;
  private enabled = true;

  constructor(private depGraph: IDependencyGraph) {}

  async observe(file: string): Promise<Signal<BoundaryData>[]> {
    const dependents = this.depGraph.getDependents(file);
    const isPublicApi = this.isPublicApiFile(file);
    const isExternal = this.hasExternalConsumers(file, dependents);

    if (!isPublicApi && !isExternal) return [];

    return [createSignal({
      type: 'impact',
      confidence: isPublicApi ? 'high' : 'medium',
      data: {
        isApiBoundary: isPublicApi || isExternal,
        boundaryType: isPublicApi ? 'public-api' : isExternal ? 'external-integration' : 'internal',
        consumers: dependents,
      },
      provenance: {
        source: this.id,
        method: 'dependency-analysis',
        version: '1.0',
        timestamp: Date.now(),
      },
      reasons: [{
        code: 'BOUNDARY_DETECTED',
        description: `File is a ${isPublicApi ? 'public API' : 'integration'} boundary`,
      }],
      filePath: file,
    })];
  }

  isEnabled(): boolean { return this.enabled; }
  setEnabled(enabled: boolean): void { this.enabled = enabled; }

  private isPublicApiFile(file: string): boolean {
    return file.includes('/api/') || file.includes('index.ts') || file.endsWith('.d.ts');
  }

  private hasExternalConsumers(file: string, dependents: string[]): boolean {
    return dependents.some(d => d.includes('node_modules') || !d.startsWith('src/'));
  }
}
