import * as vscode from 'vscode';

export interface ISecretManager {
  get(key: string): Promise<string | undefined>;
  set(key: string, value: string): Promise<void>;
  delete(key: string): Promise<void>;
  has(key: string): Promise<boolean>;
  listKeys(): Promise<string[]>;
}

const SECRET_PREFIX = 'hikaflow.';
const KEYS_LIST_KEY = 'hikaflow._keys';

export class SecretManager implements ISecretManager {
  private secrets: vscode.SecretStorage;
  private knownKeys = new Set<string>();

  constructor(context: vscode.ExtensionContext) {
    this.secrets = context.secrets;
    this.loadKnownKeys();
  }

  async get(key: string): Promise<string | undefined> {
    return this.secrets.get(SECRET_PREFIX + key);
  }

  async set(key: string, value: string): Promise<void> {
    await this.secrets.store(SECRET_PREFIX + key, value);
    this.knownKeys.add(key);
    await this.saveKnownKeys();
  }

  async delete(key: string): Promise<void> {
    await this.secrets.delete(SECRET_PREFIX + key);
    this.knownKeys.delete(key);
    await this.saveKnownKeys();
  }

  async has(key: string): Promise<boolean> {
    const value = await this.get(key);
    return value !== undefined;
  }

  async listKeys(): Promise<string[]> {
    return Array.from(this.knownKeys);
  }

  private async loadKnownKeys(): Promise<void> {
    const keysJson = await this.secrets.get(KEYS_LIST_KEY);
    if (keysJson) {
      try {
        const keys = JSON.parse(keysJson);
        this.knownKeys = new Set(keys);
      } catch {
        this.knownKeys = new Set();
