  private async findUnusedExports(rootPath: string): Promise<UnusedExport[]> {
    try {
      const { stdout } = await execAsync('npx knip --reporter json', { cwd: rootPath });
      const result = JSON.parse(stdout);

      return result.exports.map((exp: any) => ({
        category: 'unused-export',
        name: exp.name,
        filePath: exp.file,
        line: exp.line,
      }));
    } catch (error) {
      console.error('Knip analysis failed:', error);
      return [];
    }
  }

  private inferKind(exp: any): UnusedExport['kind'] {
    if (exp.type === 'class') return 'class';
    if (exp.type === 'function') return 'function';
    if (exp.type === 'type') return 'type';
    if (exp.type === 'interface') return 'interface';
    return 'const';
  }

  /**
   * Detect likely false positives to lower confidence.
   */
  private isLikelyFalsePositive(exp: any): boolean {
    // React lifecycle methods
    if (['componentDidMount', 'componentWillUnmount', 'render'].includes(exp.name)) {
      return true;
    }
    // Angular lifecycle hooks
    if (['ngOnInit', 'ngOnDestroy', 'ngOnChanges'].includes(exp.name)) {
      return true;
    }
    // Test utilities
    if (exp.file.includes('.test.') || exp.file.includes('.spec.')) {
      return true;
    }
    // Storybook
    if (exp.file.includes('.stories.')) {
      return true;
    }
    return false;
  }
