import { parseSync } from '@swc/core';

/**
 * FastAnalyzer uses SWC for structural analysis only.
 *
 * LIMITATION: No type information available.
 * For type-aware analysis, use AccurateAnalyzer.
 */
export class FastAnalyzer implements IFastAnalyzer {
  async analyze(filePath: string, content = ''): Promise<FastParseResult> {
    return this.parseFile(content);
  }

  getExports(content: string): string[] {
    return this.parseFile(content).exports;
  }

  getImports(content: string): ImportInfo[] {
    return this.parseFile(content).imports;
  }

  private parseFile(content: string): FastParseResult {
    const ast = parseSync(content, { syntax: 'typescript', tsx: true });
    // Extract exports, imports, functions, classes from AST
    // NOTE: This gives us names/structure, NOT types
    return { exports: [], imports: [], functions: [], classes: [] };
  }
}
```

