import Tinypool from 'tinypool';
import { cpus } from 'os';

export class WorkerPool implements IWorkerPool {
  private pool: Tinypool;

  constructor(workerPath: string, maxWorkers = Math.max(1, cpus().length - 1)) {
    this.pool = new Tinypool({
      filename: workerPath,
      maxThreads: maxWorkers,
      idleTimeout: 60000,
    });
  }

  async runTask<T>(task: WorkerTask): Promise<T> {
    return this.pool.run(task) as Promise<T>;
  }

  getStats(): { activeWorkers: number; queuedTasks: number } {
    return {
      queuedTasks: this.pool.queueSize,
      activeWorkers: this.pool.threads.length,
    };
  }

  async shutdown(): Promise<void> {
    await this.pool.destroy();
  }
}
