    provenance: opts.provenance,
    reasons: opts.reasons,
    filePath: opts.filePath,
    line: opts.line,
    createdAt: now,
    expiresAt: opts.ttl ? now + opts.ttl : undefined,
  };
}

export function isExpired(signal: Signal<unknown>): boolean {
