}

export function filterByConfidence(signals: Signal<unknown>[], min: ConfidenceLevel): Signal<unknown>[] {
  const order = { high: 3, medium: 2, low: 1 };
  return signals.filter(s => order[s.confidence] >= order[min]);
}
