import type { Signal, ConfidenceLevel } from './types';
import { isExpired } from './Signal';

type HikaflowMode = 'quiet' | 'default' | 'strict';
type Callback = (signal: Signal<unknown>) => void;

const MODE_LEVELS: Record<HikaflowMode, ConfidenceLevel[]> = {
  quiet: ['high'],
  default: ['high', 'medium'],
  strict: ['high', 'medium', 'low'],
};

export class SignalGateway {
  private signals = new Map<string, Signal<unknown>>();
  private byFile = new Map<string, Set<string>>();
  private subscribers = new Set<Callback>();
  private dismissed = new Set<string>();

  emit(signal: Signal<unknown>): void {
    if (this.dismissed.has(signal.id) || isExpired(signal)) return;

    this.signals.set(signal.id, signal);

    if (!this.byFile.has(signal.filePath)) {
      this.byFile.set(signal.filePath, new Set());
    }
    this.byFile.get(signal.filePath)!.add(signal.id);

    for (const cb of this.subscribers) {
      try { cb(signal); } catch {}
    }
  }

  getSignalsForFile(filePath: string): Signal<unknown>[] {
    const ids = this.byFile.get(filePath) || new Set();
    return [...ids]
      .map(id => this.signals.get(id))
      .filter((s): s is Signal<unknown> => !!s && !isExpired(s) && !this.dismissed.has(s.id));
  }

  getSignalsForMode(mode: HikaflowMode): Signal<unknown>[] {
    const levels = MODE_LEVELS[mode];
    return [...this.signals.values()]
      .filter(s => !isExpired(s) && !this.dismissed.has(s.id) && levels.includes(s.confidence));
  }

  subscribe(callback: Callback): () => void {
    this.subscribers.add(callback);
    return () => this.subscribers.delete(callback);
  }

  dismiss(signalId: string): void {
    this.dismissed.add(signalId);
    const signal = this.signals.get(signalId);
    if (signal) {
      this.signals.delete(signalId);
      this.byFile.get(signal.filePath)?.delete(signalId);
    }
  }

  clear(): void {
    this.signals.clear();
    this.byFile.clear();
    this.dismissed.clear();
  }

  getAllSignals(): Signal<unknown>[] {
    return [...this.signals.values()].filter(s => !isExpired(s) && !this.dismissed.has(s.id));
  }
}
