import type { Signal, ConfidenceLevel, SignalType } from '../../../specs/interfaces/core';

export interface ISignalPrioritizer {
  prioritize(signals: Signal<unknown>[]): Signal<unknown>[];
  getTopSignals(signals: Signal<unknown>[], count: number): Signal<unknown>[];
}

const CONFIDENCE_WEIGHTS: Record<ConfidenceLevel, number> = {
  high: 1.0,
  medium: 0.6,
  low: 0.3,
};

const TYPE_WEIGHTS: Record<SignalType, number> = {
  'breaking-change': 1.0,
  'impact': 0.9,
  'test-gap': 0.8,
  'circular-dependency': 0.7,
  'hotspot': 0.6,
  'unused-export': 0.5,
  'test-mapping': 0.4,
  'propagation': 0.4,
  'business-criticality': 0.8,
  'mutation': 0.5,
};

export class SignalPrioritizer implements ISignalPrioritizer {
  prioritize(signals: Signal<unknown>[]): Signal<unknown>[] {
    return [...signals].sort((a, b) => {
      const scoreA = this.calculateScore(a);
      const scoreB = this.calculateScore(b);
      return scoreB - scoreA;
    });
  }

  getTopSignals(signals: Signal<unknown>[], count: number): Signal<unknown>[] {
    return this.prioritize(signals).slice(0, count);
  }

  private calculateScore(signal: Signal<unknown>): number {
    let score = 0;

    // Confidence weight (0-1)
    score += CONFIDENCE_WEIGHTS[signal.confidence] * 0.4;

    // Type weight (0-1)
    score += (TYPE_WEIGHTS[signal.type] ?? 0.5) * 0.3;

    // Evidence weight (more reasons = higher score)
    const evidenceScore = Math.min(signal.reasons.length / 5, 1);
    score += evidenceScore * 0.2;

    // Recency weight (decay over 24 hours)
    const ageMs = Date.now() - signal.createdAt;
    const ageHours = ageMs / (1000 * 60 * 60);
    const recencyScore = Math.max(0, 1 - (ageHours / 24));
    score += recencyScore * 0.1;

    return score;
  }
}

export function createDefaultPrioritizer(): ISignalPrioritizer {
  return new SignalPrioritizer();
}
