import type { EvidenceWeights } from '../../../specs/interfaces/core';

export const EVIDENCE_WEIGHT_FACTORS = {
  test: 0.30,
  runtime: 0.30,
  historical: 0.20,
  static: 0.15,
  user: 0.05,
} as const;

export interface RawEvidence {
  type: keyof EvidenceWeights;
  value: number;
  scale: { min: number; max: number };
  source: string;
}

export interface NormalizedEvidence {
  type: keyof EvidenceWeights;
  normalizedValue: number;  // 0-1
  weightedValue: number;    // normalized * weight factor
  source: string;
}

export interface IEvidenceNormalizer {
  normalize(evidence: RawEvidence): NormalizedEvidence;
  aggregate(evidences: NormalizedEvidence[]): EvidenceWeights;
  calculateCompositeScore(weights: EvidenceWeights): number;
}

export class EvidenceNormalizer implements IEvidenceNormalizer {
  normalize(evidence: RawEvidence): NormalizedEvidence {
    const { min, max } = evidence.scale;
    const range = max - min;

    let normalizedValue: number;
    if (range === 0) {
      normalizedValue = evidence.value > 0 ? 1 : 0;
    } else {
      normalizedValue = Math.max(0, Math.min(1, (evidence.value - min) / range));
    }

    const weightFactor = EVIDENCE_WEIGHT_FACTORS[evidence.type];
    const weightedValue = normalizedValue * weightFactor;

    return {
      type: evidence.type,
      normalizedValue,
      weightedValue,
      source: evidence.source,
    };
  }

  aggregate(evidences: NormalizedEvidence[]): EvidenceWeights {
    const weights: EvidenceWeights = {};

    // Group by type and take max value for each type
    const byType = new Map<keyof EvidenceWeights, number[]>();

    for (const evidence of evidences) {
      const existing = byType.get(evidence.type) ?? [];
      existing.push(evidence.normalizedValue);
      byType.set(evidence.type, existing);
    }

    for (const [type, values] of byType) {
      // Use max value when multiple sources report same type
      weights[type] = Math.max(...values);
    }

    return weights;
  }

