import type { ConfidenceLevel, EvidenceWeights } from '../../../specs/interfaces/core';

// Thresholds for converting scores to levels
export const CONFIDENCE_THRESHOLDS = {
  high: 0.8,
  medium: 0.5,
  low: 0.0,
} as const;

export interface ConfidenceFactors {
  evidenceScore: number;      // 0-1 from evidence normalizer
  methodAccuracy: number;     // 0-1 based on resolution method
  recencyFactor: number;      // 0-1 based on data freshness
  calibrationAdjustment: number;  // -0.2 to +0.2 from calibration
}

/**
 * Calculate confidence level from a numeric score
 */
export function scoreToLevel(score: number): ConfidenceLevel {
  if (score >= CONFIDENCE_THRESHOLDS.high) return 'high';
  if (score >= CONFIDENCE_THRESHOLDS.medium) return 'medium';
  return 'low';
}

/**
 * Get minimum score for a confidence level
 */
export function levelToMinScore(level: ConfidenceLevel): number {
  return CONFIDENCE_THRESHOLDS[level];
}

/**
 * Calculate composite confidence score from multiple factors
 */
export function calculateConfidence(factors: ConfidenceFactors): number {
  const baseScore =
    factors.evidenceScore * 0.5 +
    factors.methodAccuracy * 0.3 +
    factors.recencyFactor * 0.2;

  // Apply calibration adjustment (bounded)
  const adjusted = baseScore + Math.max(-0.2, Math.min(0.2, factors.calibrationAdjustment));

  // Clamp to 0-1
  return Math.max(0, Math.min(1, adjusted));
}

/**
 * Calculate confidence from evidence weights
 */
export function confidenceFromEvidence(weights: EvidenceWeights): number {
  let totalWeight = 0;
  let weightedSum = 0;

  const factors: Array<[keyof EvidenceWeights, number]> = [
    ['test', 0.30],
    ['runtime', 0.30],
    ['historical', 0.20],
    ['static', 0.15],
    ['user', 0.05],
  ];

  for (const [key, factor] of factors) {
    const value = weights[key];
    if (value !== undefined) {
      weightedSum += value * factor;
      totalWeight += factor;
    }
  }

  return totalWeight > 0 ? weightedSum / totalWeight : 0;
}

