## Priority
**CRITICAL** - Must be completed before any MCP integration

## Context

The Model Context Protocol (MCP) has significant security vulnerabilities documented in 2025:
- **CVE-2025-6514** (CVSS 9.6) - Proxy configuration vulnerability
- Prompt injection attacks via tool descriptions
- Tool poisoning attacks
- Token/credential theft from MCP servers
- WhatsApp data exfiltration demonstrated by Invariant Labs
- GitHub private repo leaks via malicious issues

See: https://strobes.co/blog/mcp-model-context-protocol-and-its-critical-vulnerabilities/

## Implementation

### 1. MCP Server Validator

```typescript
// src/security/mcp-validator.ts
import { z } from 'zod';

export interface MCPServerConfig {
  name: string;
  url: string;
  tools: string[];
  trustedSource: boolean;
}

export interface MCPValidationResult {
  valid: boolean;
  warnings: string[];
  blockedTools: string[];
  reason?: string;
}

export class MCPServerValidator {
  private trustedServers = new Set<string>([
    'github.com/modelcontextprotocol',
    'github.com/anthropics',
  ]);

  private suspiciousPatterns = [
    /ignore\s+previous/i,
    /you\s+are\s+now/i,
    /pretend\s+to\s+be/i,
    /system\s+prompt/i,
    /\bexfiltrate\b/i,
    /send\s+to\s+external/i,
  ];

  async validate(server: MCPServerConfig): Promise<MCPValidationResult> {
    const warnings: string[] = [];
    const blockedTools: string[] = [];

    // Check if from trusted source
    if (!server.trustedSource && !this.isTrustedSource(server.url)) {
      warnings.push(`Server '${server.name}' is not from a trusted source`);
    }

    // Validate tool descriptions for injection attempts
    for (const tool of server.tools) {
      if (this.containsSuspiciousContent(tool)) {
        blockedTools.push(tool);
        warnings.push(`Tool '${tool}' contains suspicious patterns`);
      }
    }

    return {
      valid: blockedTools.length === 0,
      warnings,
      blockedTools,
      reason: blockedTools.length > 0
        ? 'Potential tool poisoning detected'
        : undefined,
    };
  }

  private isTrustedSource(url: string): boolean {
    return Array.from(this.trustedServers).some(trusted =>
      url.includes(trusted)
    );
  }

  private containsSuspiciousContent(content: string): boolean {
    return this.suspiciousPatterns.some(pattern => pattern.test(content));
  }

  addTrustedSource(source: string): void {
    this.trustedServers.add(source);
  }
}
