import type { IDependencyGraph } from '../../core/graph/DependencyGraph';
import type { ICallGraphBuilder } from '../../core/graph/CallGraphBuilder';
import type { Budget, Signal, Provenance } from '../../../specs/interfaces/core';
import type { ImpactSignalData } from '../../../specs/interfaces/analysis';

export class ImpactCalculator implements IImpactCalculator {
  constructor(
    private depGraph: IDependencyGraph,
    private callGraph: ICallGraphBuilder
  ) {}

  async calculateImpact(
    file: string,
    changedSymbols: string[],
    budget: Budget
  ): Promise<Signal<ImpactSignalData>> {
    const result = this.depGraph.getBlastRadius(file, budget);
    const affectedTests = this.findAffectedTests(file);
    const data: ImpactSignalData = {
      ...result,
      testCoverage: result.testCoverage ?? 0,
      changedSymbols,
      affectedTests,
    };

    const provenance: Provenance = {
      source: 'fast-analyzer',
      method: 'heuristic',
      version: '1.0.0',
      timestamp: Date.now(),
    };

    return {
      id: `impact-${file}-${Date.now()}`,
      type: 'impact',
      confidence: 'medium',
      data,
      provenance,
      reasons: [],
      filePath: file,
      createdAt: Date.now(),
    };
  }

  private findAffectedTests(file: string): string[] {
    const deps = this.depGraph.getDependents(file);
    return deps.filter(d => d.includes('.test.') || d.includes('.spec.'));
  }
}
