import type { IDependencyGraph } from '../../core/graph/DependencyGraph';
import type { ITestMapper, TestMapping } from '../../../specs/interfaces/analysis';

export class TestMapper implements ITestMapper {
  private testToSource = new Map<string, string>();
  private sourceToTests = new Map<string, Set<string>>();

  constructor(private depGraph: IDependencyGraph) {}

  async findTests(sourceFile: string): Promise<TestMapping> {
    // Strategy 1: Convention-based (*.test.ts, *.spec.ts)
    // Strategy 2: Import analysis (tests that import the source)
    // Strategy 3: Co-location (same directory)

    const tests = this.sourceToTests.get(sourceFile);
    const discovered = tests ? [...tests] : [
      ...new Set([...this.findByConvention(sourceFile), ...this.findByImports(sourceFile)]),
    ];

    return {
      sourceFile,
      testFiles: discovered,
      discoveryMethod: discovered.length ? 'convention' : 'import',
      confidence: discovered.length ? 'medium' : 'low',
    };
  }

  async findTestsForSymbol(filePath: string, symbolName: string): Promise<TestMapping> {
    // Default: fall back to file-level mapping
    return this.findTests(filePath);
  }

  async getTestCoverage(sourceFile: string): Promise<number | null> {
    const mapping = await this.findTests(sourceFile);
    // Analyze coverage based on imports and mocks
    return mapping.testFiles.length > 0 ? 50 : 0;
  }

  private findByConvention(sourceFile: string): string[] {
    // Example patterns: foo.test.ts, foo.spec.ts, __tests__/foo.test.ts
    const candidates = [
      sourceFile.replace(/\.tsx?$/, '.test.ts'),
      sourceFile.replace(/\.tsx?$/, '.spec.ts'),
      sourceFile.replace(/\/([^/]+)\.tsx?$/, '/__tests__/$1.test.ts'),
    ];
    return candidates.filter(p => this.fileExists(p));
  }

  private findByImports(sourceFile: string): string[] {
    // Use dependency graph: tests that import sourceFile
    return this.depGraph.getDependents(sourceFile).filter(f =>
      /\.(test|spec)\.(ts|tsx|js|jsx)$/.test(f)
    );
  }

  private fileExists(filePath: string): boolean {
    // Implementation detail: use fs.existsSync in real code
    return true;
  }
}
